<script lang="ts">
 import {onMount} from 'svelte';import {Api} from '$lib/api';let panels=$state<any[]>([]);let error=$state('');
 async function load(){try{const values=await Promise.all([Api.debugStats(),Api.debugLogTail(),Api.debugNoiseFloor(),Api.debugClassifications(),Api.debugDsdStderr(),Api.debugVdl2Stderr(),Api.debugRtl433Stderr()]);panels=['Stats','Application log','Noise floor','Classifications','DSD stderr','VDL2 stderr','rtl_433 stderr'].map((title,i)=>({title,value:values[i]}));error=''}catch(e){error=String(e)}}onMount(load);
 function text(v:any){if(typeof v==='string')return v;if(Array.isArray(v))return v.map((x,i)=>`${i+1}. ${text(x)}`).join('\n');if(v&&typeof v==='object')return Object.entries(v).map(([k,x])=>`${k.replaceAll('_',' ')}: ${text(x)}`).join('\n');return String(v??'—')}
</script>
<div class="page"><div class="heading"><div><h1>Debug</h1><p class="muted">Runtime statistics, classifier state and decoder logs.</p></div><button onclick={load}>Refresh all</button></div>{#if error}<p class="error">{error}</p>{/if}<div class="grid">{#each panels as panel}<section class="card"><h2>{panel.title}</h2><pre>{text(panel.value)}</pre></section>{/each}</div></div>
<style>.page{padding:16px;overflow-y:auto;height:100%}.heading{display:flex;justify-content:space-between;align-items:center}.muted{color:var(--fg-dim)}.error{color:var(--danger)}button{background:var(--bg);color:var(--fg);border:1px solid var(--line);padding:7px 11px;border-radius:5px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:12px}.card{background:var(--bg-elev);border:1px solid var(--line);border-radius:8px;padding:12px;min-width:0}h2{font-size:13px;color:var(--accent-2);margin:0 0 8px}pre{margin:0;background:var(--bg);padding:9px;max-height:260px;overflow:auto;white-space:pre-wrap;word-break:break-word;font:11px var(--mono)}</style>
